export function normalizeMarkdown(markdown) {
  return `${markdown.replace(/\n{3,}/gu, '\n\n').replace(/\n+$/u, '\n')}`;
}

export function header(title, sourceName) {
  return normalizeMarkdown([
    `# ${title}`,
    '',
    '> AUTO-GENERATED by `scripts/generate-runtime-spec-kernel-docs.mjs`. DO NOT EDIT.',
    `> Source: \`.nimi/spec/runtime/kernel/tables/${sourceName}\``,
    '',
  ].join('\n'));
}

export function mdBool(value) {
  return value ? 'true' : 'false';
}

export function renderGeneratedIndex(entries) {
  let out = [
    '# Generated Kernel Views',
    '',
    '> AUTO-GENERATED by `scripts/generate-runtime-spec-kernel-docs.mjs`. DO NOT EDIT.',
    '',
    '| File | Source |',
    '|---|---|',
  ].join('\n');

  for (const entry of entries) {
    out += `\n| \`${entry.output}\` | \`tables/${entry.input}\` |`;
  }
  out += '\n';

  return normalizeMarkdown(out);
}

